SELECT f.id as facilityId, f.name as facilityName, f.type as facilityType, COALESCE(COUNT(r.id), 0) as totalReservations, COALESCE(SUM(r.total_price), 0) as totalRevenue, COALESCE(COUNT(CASE WHEN r.status = 1 THEN 1 END), 0) as paidReservations, COALESCE(COUNT(CASE WHEN r.status = 2 THEN 1 END), 0) as usedReservations, COALESCE(COUNT(CASE WHEN r.status = 3 THEN 1 END), 0) as cancelledReservations, COALESCE(COUNT(CASE WHEN r.status = 0 THEN 1 END), 0) as pendingReservations FROM sports_facility f LEFT JOIN reservation r ON f.id = r.facility_id WHERE f.id = #{facilityId}
AND r.reservation_date >= #{startDate}
AND r.reservation_date <= #{endDate}
GROUP BY f.id

SELECT f.id as facilityId, f.name as facilityName, f.type as facilityType, COUNT(r.id) as totalReservations, COALESCE(SUM(r.total_price), 0) as totalRevenue, COUNT(CASE WHEN r.status = 1 THEN 1 END) as paidReservations, COUNT(CASE WHEN r.status = 2 THEN 1 END) as usedReservations FROM sports_facility f LEFT JOIN reservation r ON f.id = r.facility_id
AND r.reservation_date >= #{startDate}
AND r.reservation_date <= #{endDate}
GROUP BY f.id ORDER BY totalReservations DESC

