UPDATE sports_facility
name = #{name}, type = #{type}, location = #{location}, description = #{description}, image_url = #{imageUrl}, capacity = #{capacity}, price_per_hour = #{pricePerHour}, max_duration = #{max_duration}, open_time = #{openTime}, close_time = #{closeTime}, status = #{status}, update_time = NOW()
WHERE id = #{id}
